def solution(board):
    seen = set()
    for r in range(9):
        for c in range(9):
            val = board[r][c]
            if val != '.':
                row_key = f'r_{r}_{val}'
                col_key = f'c_{c}_{val}'
                box_key = f'b_{r//3}_{c//3}_{val}'
                if row_key in seen or col_key in seen or box_key in seen:
                    return False
                seen.add(row_key)
                seen.add(col_key)
                seen.add(box_key)
    return True
